const data = $input.item.json.body || $input.item.json;

// --- 1. DATENVALIDIERUNG ---
const ingredients = data.ingredients;
const preferences = data.preferences;

if (!ingredients || !Array.isArray(ingredients) || ingredients.length === 0) {
  return { json: { allowed: false, status: 400, message: "Ungültige Daten: 'ingredients' fehlt oder ist leer." } };
}

if (!preferences || typeof preferences.portions !== 'number' || typeof preferences.persons !== 'number') {
  return { json: { allowed: false, status: 400, message: "Ungültige Daten: 'portions' oder 'persons' fehlerhaft." } };
}

// --- 2. RATE-LIMITING (Kostenairbag) ---
const staticData = $getWorkflowStaticData('global');
const now = new Date().getTime();
const ONE_HOUR = 60 * 60 * 1000;
const MAX_REQUESTS_PER_HOUR = 50; // Kostenairbag

if (!staticData.lastReset || (now - staticData.lastReset) > ONE_HOUR) {
  staticData.requestCount = 0;
  staticData.lastReset = now;
}

if (staticData.requestCount >= MAX_REQUESTS_PER_HOUR) {
  return { json: { allowed: false, status: 429, message: "Rate-Limit erreicht. Zu viele Anfragen in der letzten Stunde (Kostenairbag aktiv)." } };
}

staticData.requestCount++;

return { json: { allowed: true, data: data } };

